import Card from "./card";

import styles from "./styles.m"

const UsersList = (props) => {
  const { users } = props;

  return (
    <Card className={styles}>
      <ul>
        {users &&
          users.map((user, i) => (
            <li key={i}>
              {user.name} ({user.age} years old)
            </li>
          ))}
      </ul>
    </Card>
  );
};

export default UsersList;
